VAR
    Start_Delay_Timer : TON;
END_VAR

// Monitor starting performance
// Start timer if motor is commanded to run and energized
// Trip if speed is < 50 rpm after 5 seconds
Start_Delay_Timer(IN := Start_Command AND Motor_Running AND (Motor_Speed < 50.0), PT := T#5S);

IF Start_Delay_Timer.Q THEN
    Motor_Stop := TRUE;
END_IF;

